CREATE TABLE public.chat_message_receipts (kind text NOT NULL CHECK(kind IN ('inbox','peer','group')), message_id uuid NOT NULL, user_id uuid NOT NULL, delivered_at timestamptz, read_at timestamptz, PRIMARY KEY(kind,message_id,user_id));
GRANT SELECT ON public.chat_message_receipts TO authenticated;
GRANT ALL ON public.chat_message_receipts TO service_role;
ALTER TABLE public.chat_message_receipts ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_receipts ON public.chat_message_receipts FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE FUNCTION public.initialize_chat_receipts() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF TG_TABLE_NAME='community_chat_messages' THEN INSERT INTO public.chat_message_receipts(kind,message_id,user_id) VALUES('peer',NEW.id,NEW.recipient_id); ELSE INSERT INTO public.chat_message_receipts(kind,message_id,user_id) SELECT 'group',NEW.id,m.user_id FROM public.community_group_members m WHERE m.group_id=NEW.group_id AND m.user_id<>NEW.sender_id; END IF; RETURN NEW; END $$;
REVOKE ALL ON FUNCTION public.initialize_chat_receipts() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER peer_receipt_targets AFTER INSERT ON public.community_chat_messages FOR EACH ROW EXECUTE FUNCTION public.initialize_chat_receipts();
CREATE TRIGGER group_receipt_targets AFTER INSERT ON public.community_group_messages FOR EACH ROW EXECUTE FUNCTION public.initialize_chat_receipts();
CREATE FUNCTION public.acknowledge_chat_messages(_kind text,_ids uuid[],_read boolean DEFAULT false) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE mid uuid; valid boolean; BEGIN IF auth.uid() IS NULL OR cardinality(_ids)>250 OR _kind NOT IN ('inbox','peer','group') THEN RAISE EXCEPTION 'forbidden'; END IF; FOREACH mid IN ARRAY _ids LOOP valid:=false; IF _kind='peer' THEN SELECT EXISTS(SELECT 1 FROM public.community_chat_messages WHERE id=mid AND recipient_id=auth.uid()) INTO valid; ELSIF _kind='group' THEN SELECT EXISTS(SELECT 1 FROM public.community_group_messages m WHERE m.id=mid AND m.sender_id<>auth.uid() AND public.is_community_group_member(m.group_id,auth.uid())) INTO valid; ELSE SELECT EXISTS(SELECT 1 FROM public.messages m LEFT JOIN public.leads l ON l.id=m.lead_id WHERE m.id=mid AND m.direction='inbound' AND ((l.workspace_owner_id=public.current_workspace_owner() AND public.can_access_lead_in_current_workspace(l.id,l.assigned_to)) OR (m.lead_id IS NULL AND public.is_admin_or_above(auth.uid()) AND m.platform='whatsapp' AND m.metadata->>'sender_phone' IS NOT NULL))) INTO valid; END IF; IF valid THEN INSERT INTO public.chat_message_receipts(kind,message_id,user_id,delivered_at,read_at) VALUES(_kind,mid,auth.uid(),now(),CASE WHEN _read THEN now() END) ON CONFLICT(kind,message_id,user_id) DO UPDATE SET delivered_at=coalesce(chat_message_receipts.delivered_at,excluded.delivered_at),read_at=coalesce(chat_message_receipts.read_at,excluded.read_at); END IF; END LOOP; END $$;
REVOKE ALL ON FUNCTION public.acknowledge_chat_messages(text,uuid[],boolean) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.acknowledge_chat_messages(text,uuid[],boolean) TO authenticated;
CREATE FUNCTION public.chat_receipt_states(_kind text,_ids uuid[]) RETURNS TABLE(message_id uuid,delivery_status text,viewer_read boolean) LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.uid() IS NULL OR cardinality(_ids)>250 THEN RAISE EXCEPTION 'forbidden'; END IF; RETURN QUERY SELECT t.id,CASE WHEN count(r.user_id)>0 AND bool_and(r.read_at IS NOT NULL) THEN 'read' WHEN count(r.user_id)>0 AND bool_and(r.delivered_at IS NOT NULL) THEN 'delivered' ELSE 'sent' END,bool_or(r.user_id=auth.uid() AND r.read_at IS NOT NULL) FROM (SELECT m.id FROM public.community_chat_messages m WHERE _kind='peer' AND m.id=ANY(_ids) AND auth.uid() IN(m.sender_id,m.recipient_id) UNION ALL SELECT m.id FROM public.community_group_messages m WHERE _kind='group' AND m.id=ANY(_ids) AND public.is_community_group_member(m.group_id,auth.uid()) UNION ALL SELECT m.id FROM public.messages m JOIN public.leads l ON l.id=m.lead_id WHERE _kind='inbox' AND m.id=ANY(_ids) AND l.workspace_owner_id=public.current_workspace_owner() AND public.can_access_lead_in_current_workspace(l.id,l.assigned_to) UNION ALL SELECT m.id FROM public.messages m WHERE _kind='inbox' AND m.id=ANY(_ids) AND m.lead_id IS NULL AND public.is_admin_or_above(auth.uid()) AND m.platform='whatsapp' AND m.direction='inbound' AND m.metadata->>'sender_phone' IS NOT NULL) t LEFT JOIN public.chat_message_receipts r ON r.kind=_kind AND r.message_id=t.id GROUP BY t.id; END $$;
REVOKE ALL ON FUNCTION public.chat_receipt_states(text,uuid[]) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.chat_receipt_states(text,uuid[]) TO authenticated;